function scheduleFields(){clearTimeout(fieldTimer);fieldTimer=setTimeout(()=>{if(document.activeElement?.matches('input:not([type=checkbox]),textarea')){scheduleFields();return}task(async()=>{})},350)}
function markFields(){fieldsDirty=true;serializedProject=null;autosaved=false;path=null;simulation=null;playing=false;$('play').textContent='Play paths';$('stats').textContent='Changed · generate to refresh';$('saved').textContent='Saving…';historyButtons();draw();scheduleFields()}
function historyButtons(){$('undo').disabled=busy||(!canUndo&&!fieldsDirty);$('redo').disabled=busy||fieldsDirty||!canRedo;const planned=project&&project.process!=='milling';for(const id of ['surface','plan','recognize','generate','export','simulate','nc-preview','add'])$(id).disabled=busy||planned;$('replace-library').disabled=busy||project?.operations.length>0;if(project?.operations.length)$('replace-library').checked=false;$('save-stock').disabled=busy||!simulation}
function applyView(view){project=view.project;serializedProject=null;workspacePreview=view.workspace_preview||[];canUndo=view.can_undo;canRedo=view.can_redo}
function persist(){try{const data=projectJSON();const previous=localStorage.getItem('oc-project');let backupWarning=false;if(previous&&previous!==data){try{localStorage.setItem('oc-backup',previous)}catch{backupWarning=true}}localStorage.setItem('oc-project',data);autosaved=true;$('saved').textContent=backupWarning?'Saved on this device · previous backup could not be refreshed':'Saved on this device';return true}catch{autosaved=false;$('saved').textContent='Not saved — download a backup';status('Browser storage unavailable or full. Download a backup before closing.',true);return false}}
async function sessionEdit(edit){applyView(await call('session-edit',{edit}));if(edit.kind==='move_operation')selected=edit.target;if(edit.kind==='duplicate_operation')selected=edit.index+1;if(edit.kind==='feature_operation')selected=project.operations.length-1;await changed(false);render()}
function createEngine(){const engine=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});
engine.onmessage=({data})=>{const p=pending.get(data.id);if(!p)return;if(data.progress){status(data.progress);return}pending.delete(data.id);data.error?p.reject(Error(data.error)):p.resolve(data.value)};
engine.onerror=()=>{for(const p of pending.values())p.reject(Error('CAM engine failed to load. Rebuild or reload the app.'));pending.clear()};
return engine;}
function engineCall(action,extra={}){return new Promise((resolve,reject)=>{const id=++sequence;pending.set(id,{resolve,reject});const message={id,action,...(['session-start','normalize','draft'].includes(action)?{project:projectJSON()}:{}),...extra};worker.postMessage(message,extra.file?[extra.file.bytes]:[])})}
async function call(action,extra={}){
 if(busy&&lastState&&['generate','recognize','simulate-current','plan-model','import','stock-obj'].includes(action)){
  const history=await engineCall('history-checkpoint');jobCheckpoint={history,project:lastState};$('job-controls').hidden=false;$('cancel-job').disabled=false;
 }
 return engineCall(action,extra);
}
$('cancel-job').onclick=()=>{
 if(!busy||!jobCheckpoint||restarting)return;
 $('cancel-job').disabled=true;const saved=jobCheckpoint;worker.onmessage=null;worker.onerror=null;worker.terminate();for(const p of pending.values()){const error=Error('Calculation cancelled. Workspace and undo history preserved.');error.name='AbortError';p.reject(error);}pending.clear();worker=createEngine();
 restarting=engineCall('restore-session',{project:saved.project,history:saved.history}).then(view=>{canUndo=view.can_undo;canRedo=view.can_redo}).catch(error=>{status(`Engine recovery failed: ${error.message}. Download a backup and reload.`,true)});
};
function status(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error)}
async function task(fn){if(busy)return;busy=true;document.querySelectorAll('button,input,select,textarea').forEach(b=>b.disabled=true);try{if(fieldsDirty){clearTimeout(fieldTimer);fieldsDirty=false;await changed(true,true);render()}await fn()}catch(e){status(e.message,e.name!=='AbortError')}finally{if(restarting)await restarting;restarting=null;jobCheckpoint=null;$('job-controls').hidden=true;busy=false;document.querySelectorAll('button,input,select,textarea').forEach(b=>b.disabled=false);historyButtons()}}
async function changed(record=true,keepPresentation=false){
 if(record){serializedProject=null;autosaved=false;$('saved').textContent='Saving…';try{const view=await call('session-edit',{edit:{kind:'replace',project}});if(keepPresentation){workspacePreview=view.workspace_preview||[];canUndo=view.can_undo;canRedo=view.can_redo;viewport.scene=null}else applyView(view)}catch(e){project=JSON.parse(lastState);serializedProject=lastState;render();persist();throw e}}
 lastState=projectJSON();revision++;path=null;simulation=null;highlight=null;playing=false;$('play').textContent='Play paths';$('show-simulation').checked=false;$('nc-code').textContent='';$('planning-notes').textContent='';status('Project changed · generate to refresh paths');$('stats').textContent='Changed · generate to refresh';$('result').textContent='';$('features').replaceChildren();refreshEditor();persist();historyButtons();draw()
}
function field(parent,label,obj,key,type='number',choices,factor=1){const wrap=document.createElement('label');wrap.textContent=label;const input=document.createElement(choices?'select':'input');input.setAttribute('aria-label',label);if(choices){for(const [value,name] of choices){const o=document.createElement('option');o.value=value;o.textContent=name;input.append(o)}}else{input.type=['optional','integer','optional-integer'].includes(type)?'number':type;if(input.type==='number')input.step=type.includes('integer')?'1':'any';if(type.startsWith('optional'))input.placeholder='Use default'}if(type==='checkbox')input.checked=obj[key];else input.value=typeof obj[key]==='number'?obj[key]/factor:obj[key]??'';const update=()=>{if(busy)return;obj[key]=type==='id'?(input.value===''?null:Number(input.value)):['optional','optional-integer'].includes(type)?(input.value===''?null:input.valueAsNumber*factor):['number','integer'].includes(type)?input.valueAsNumber*factor:type==='checkbox'?input.checked:input.value;if(obj===project&&key==='active_tool')project.active_preset=project.tool_library.tools.find(t=>t.id===project.active_tool)?.default_preset??null;if(key==='tool_id')obj.preset_id=null;markFields()};input.oninput=update;input.onchange=update;wrap.append(input);parent.append(wrap)}
function render(){if(!project)return;const openDetails=new Set([...document.querySelectorAll('.side-panels details[open]')].map(el=>el.querySelector('summary')?.textContent));selected=Math.max(0,Math.min(selected,project.operations.length-1));$('title').textContent=project.name;$('title').title=project.name;$('count').textContent=project.operations.length;$('setup').replaceChildren();field($('setup'),'Project name',project,'name','text');for(const [k,n] of [['width','Stock X · mm'],['height','Stock Y · mm'],['thickness','Stock Z · mm']])field($('setup'),n,project.stock,k);field($('setup'),'Clearance · mm',project,'clearance');
if(project.part)for(let i=0;i<3;i++)field($('setup'),`Part offset ${'XYZ'[i]} · mm`,project.part.offset,i);
renderSetup();renderExtras();$('operations').replaceChildren();project.operations.forEach((op,i)=>{const b=document.createElement('button');b.className='op'+(i===selected?' selected':'');b.textContent=`${String(i+1).padStart(2,'0')}  ${op.name}${op.enabled?'':' · disabled'}`;b.onclick=()=>{selected=i;render()};b.oncontextmenu=event=>{event.preventDefault();showOperationMenu(i,event.clientX,event.clientY)};const row=document.createElement('div');row.className='operation-row';const enabled=document.createElement('input');enabled.type='checkbox';enabled.checked=op.enabled;enabled.setAttribute('aria-label',`Enable operation ${i+1}: ${op.name}`);enabled.onchange=()=>task(async()=>{op.enabled=enabled.checked;await changed();render()});row.append(enabled,b);$('operations').append(row)});$('editor').replaceChildren();const op=project.operations[selected];if(op){field($('editor'),'Name',op,'name','text');field($('editor'),'Enabled',op,'enabled','checkbox');field($('editor'),'Strategy',op,'strategy','text',[['pocket','Rectangular pocket'],['outside_profile','Outside profile'],['inside_profile','Inside profile'],['drill','Peck drilling'],['facing','Facing'],['circular_pocket','Circular pocket'],['stock_rough','Stock roughing'],['surface_rough','3D roughing'],['parallel_finish','Parallel finish']]);if(project.tool_library.tools.length){field($('editor'),'Operation tool',op,'tool_id','id',[['','Use setup active tool'],...project.tool_library.tools.filter(t=>t.uses.includes(project.process)).map(t=>[String(t.id),t.name])]);const tool=project.tool_library.tools.find(t=>t.id===(op.tool_id??project.active_tool));if(tool)field($('editor'),'Operation preset',op,'preset_id','id',[['','Tool default preset'],...tool.presets.map(p=>[String(p.id),p.name])])}for(const k of ['x','y','width','height','depth'])field($('editor'),`${k} · mm`,op,k);const del=document.createElement('button');del.textContent='Delete operation';del.onclick=()=>task(()=>sessionEdit({kind:'delete_operation',index:selected}));$('editor').append(del);for(const [label,kind,target] of [['Duplicate operation','duplicate_operation',null],['Move operation up','move_operation',selected-1],['Move operation down','move_operation',selected+1]]){const button=document.createElement('button');button.textContent=label;button.onclick=()=>task(()=>sessionEdit({kind,index:selected,...(target===null?{}:{target})}));$('editor').append(button)}}refreshEditor();for(const details of document.querySelectorAll('.side-panels details'))if(openDetails.has(details.querySelector('summary')?.textContent))details.open=true;draw()}
